Here is a generic debounce utility:

```typescript
function debounce<T extends (...args: unknown[]) => void>(
  fn: T,
  delayMs: number
): (...args: Parameters<T>) => void {
  let timer: ReturnType<typeof setTimeout>;
  return (...args) => {
    clearTimeout(timer);
    timer = setTimeout(() => fn(...args), delayMs);
  };
}
```

Usage:

```typescript
const handleInput = debounce((value: string) => {
  console.log('search:', value);
}, 300);

document.getElementById('search')!.addEventListener('input', (e) => {
  handleInput((e.target as HTMLInputElement).value);
});
```

Yes — return a `cancel` method alongside the debounced function:

```typescript
function debounce<T extends (...args: unknown[]) => void>(
  fn: T,
  delayMs: number
): T & { cancel: () => void } {
  let timer: ReturnType<typeof setTimeout>;
  const debounced = (...args: Parameters<T>) => {
    clearTimeout(timer);
    timer = setTimeout(() => fn(...(args as unknown[])), delayMs);
  };
  debounced.cancel = () => clearTimeout(timer);
  return debounced as T & { cancel: () => void };
}
```

Call `handleInput.cancel()` to stop any pending invocation before it fires.
